WITH p AS (SELECT %s::smallint nam,coalesce(%s::text,'') ma_kho,coalesce(%s::text,'') ma_vt,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR (coalesce(u.ds_branchs,'')='' AND coalesce(u.ds_stocks,'')='') unrestricted FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.nam,a.ma_kho,a.ma_vt,a.ma_lo,a.so_seri_vt,a.ma_vi_tri,a.tk_vt,a.ton00,a.du00,a.gia00,a.status,count(*) OVER() total FROM public.cdbsp a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.nam=s.nam AND(s.ma_kho='' OR a.ma_kho=ANY(string_to_array(s.ma_kho,',')))AND(s.ma_vt='' OR a.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.unrestricted OR EXISTS(SELECT 1 FROM public.dmkho w WHERE w.ma_kho=a.ma_kho AND w.ma_dvcs=ANY(string_to_array(s.bs,',')))) ORDER BY a.ma_kho,a.ma_vt,a.ma_lo,a.ma_vi_tri LIMIT(SELECT lim FROM p);
